const nrm = (p) => (p.lead === 'feint' ? { ...p, lead: 'jab', fnt: 'lead' } : p);   /* a plan written for the main page's Feint card = a feinted jab */
const stOf = (p, sl) => (sl === 'feet' ? FEET[p.feet].st : !p[sl] ? 0 : p.fnt === sl ? 1 : ACT[p[sl]].st);
const cost = (p0) => { const p = nrm(p0); return stOf(p, 'lead') + stOf(p, 'rear') + FEET[p.feet].st + (p.clinch ? 1 : 0); };

function resolve(S, P) { const ev = [], f = S.f, say = (k, o) => ev.push({ k, ...o });
  for (const k of [0, 1]) P[k] = nrm(P[k]);
  if (S.t === N.beats) for (const m of f) m.lead = m.off = 0;   /* MMCTOY1: a new round starts level - nobody has the lead, nobody is off rhythm */
  const off = [f[0].off || 0, f[1].off || 0], was = f.map((m, k) => (m.last ? { hl: m.last.hl, hr: m.last.hr } : { hl: P[k].hl, hr: P[k].hr })); for (const m of f) m.off = 0;   /* off rhythm (he bit on a feint last beat): no counter bonus this beat, and in moment 1 his hands are still where he held them last beat */
  const give = (k) => { f[k].lead = 1; f[1 - k].lead = 0; }; let cd = -1;   /* THE LEAD: with the lead, your punch lands first when both men throw at the same speed in the same moment. cd: who created distance */

if (D.hp <= 0) continue;
