          say(sh.k, { m: i, t: 'flat', a: 'feints the ' + a.n, fe: bit ? 'bit' : 'called', o: bit ? `${v ? 'he' : 'you'} covered it: ${v ? 'he is' : 'you are'} off rhythm next beat` : `${v ? 'he' : 'you'} did not bite: ${v ? 'he takes' : 'you take'} the lead` }); continue; }
